import React from "react";
import styled from "styled-components";

const Overlay = styled.div`
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.45);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 9999;
`;

const Box = styled.div`
  width: 750px;
  max-height: 80vh;
  background: #fff;
  border-radius: 12px;
  padding: 24px;
  overflow-y: auto;
  box-shadow: 0 4px 20px rgba(0,0,0,0.2);

  h2 {
    margin-top: 0;
    color: #4A5174;
  }
`;

interface Props {
  open: boolean;
  onClose: () => void;
    children: React.ReactNode;
    filePath: string; 
}

const TermsPopup: React.FC<Props> = ({ open, onClose, children }) => {
  if (!open) return null;

  return (
    <Overlay onClick={onClose}>
      <Box onClick={(e) => e.stopPropagation()}>
        <h2>Terms & Conditions</h2>
        {children}
      </Box>
    </Overlay>
  );
};

export default TermsPopup;
